  // Validate options
  if (options === null || typeof options !== 'object') {
    throw new TableError('BAD_OPTIONS', 'options must be an object');
  }

  const { widths, align, header } = options;

  // Validate widths
  if (
    !Array.isArray(widths) ||
    widths.length === 0 ||
    !widths.every((w) => Number.isInteger(w) && w > 0)
  ) {
    throw new TableError('BAD_WIDTH', 'widths must be a non-empty array of positive integers');
  }

  // Validate align
  if (align !== undefined) {
    if (!Array.isArray(align) || align.length !== widths.length) {
      throw new TableError('BAD_ALIGN', `align must have ${widths.length} entries`);
    }
    for (const a of align) {
      if (!ALIGNMENTS.has(a)) {
        throw new TableError('BAD_ALIGN', `unknown alignment: ${a}`);
      }
    }
  }

  // Validate rows
  if (!Array.isArray(rows)) {
    throw new TableError('BAD_ROWS', 'rows must be an array');
  }

  // Return empty string if no rows
  if (rows.length === 0) {
    return '';
  }

  // Validate each row and its cells
  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    const cellCount = Array.isArray(row) ? row.length : 0;
    if (cellCount !== widths.length) {
      throw new TableError(
        'BAD_ROW_LENGTH',
        `row ${i} has ${cellCount} cells, expected ${widths.length}`,
      );
    }
    for (let j = 0; j < widths.length; j++) {
      if (typeof row[j] !== 'string') {
        throw new TableError('BAD_CELL', `cell at row ${i}, column ${j} is not a string`);
      }
    }
  }

  // Default align to all 'left'
  const alignments = align || Array(widths.length).fill('left');

  // Wrap each cell
  const wrappedRows = [];
  for (const row of rows) {
    const wrappedCells = [];
    for (let j = 0; j < widths.length; j++) {
      wrappedCells.push(wrapCell(row[j], widths[j]));
    }
    wrappedRows.push(wrappedCells);
  }

  // Build output lines
  const outputLines = [];

  for (let rowIndex = 0; rowIndex < wrappedRows.length; rowIndex++) {
    const wrappedRow = wrappedRows[rowIndex];

    // Find max height of cells in this row
    let maxHeight = 0;
    for (const wrapped of wrappedRow) {
      maxHeight = Math.max(maxHeight, wrapped.length);
    }

    // For each line in the row
    for (let lineIndex = 0; lineIndex < maxHeight; lineIndex++) {
      const lineParts = [];
      for (let j = 0; j < widths.length; j++) {
        const wrapped = wrappedRow[j];
        const line = lineIndex < wrapped.length ? wrapped[lineIndex] : '';
        const padded = padCell(line, widths[j], alignments[j]);
        lineParts.push(padded);
      }
      outputLines.push(lineParts.join(' | '));
    }

    // Add header rule after first row if header is true
    if (header && rowIndex === 0) {
      const ruleWidths = widths.map(
        (w, i) => w + (i > 0 ? 1 : 0) + (i < widths.length - 1 ? 1 : 0),
      );
      const ruleParts = ruleWidths.map((w) => '-'.repeat(w));
      outputLines.push(ruleParts.join('+'));
    }
  }

  return outputLines.join('\n');
}"}

